      options: { plugins: { legend: legB, tooltip: { mode: 'index', intersect: false, callbacks: { label: function (c) { return c.dataset.label + ': ' + fmt(c.raw, 0) + '% of windows recover the cost'; } } } }, scales: { x: Object.assign(axis({ title: 'expected benefit-cost ratio' }), { ticks: tick }), y: Object.assign(axis({ title: '% of windows that recover the cost' }), { min: 0, max: 100, ticks: tick }) } }
