    var DB = [['No recorded loss', function (q) { return q === 0; }], ['Under half the average', function (q) { return q > 0 && q < 0.5; }], ['Half to one times', function (q) { return q >= 0.5 && q < 1; }], ['One to two times', function (q) { return q >= 1 && q < 2; }], ['Over twice the average', function (q) { return q >= 2; }]];
