      data: { labels: BIN.map(function (b) { return b[1]; }), datasets: [{ label: '% of 2,000 simulated horizons', data: BIN.map(function () { return 0; }), backgroundColor: [GREY, VERM, VERM, TEAL, TEAL, INDIGO, INDIGO], borderRadius: 2 }] },
      options: { layout: { padding: { top: 18 } }, plugins: { legend: { display: false }, tooltip: { callbacks: { label: function (c) { return fmt(c.raw, 0) + '% of horizons realise this return per $1'; } } } }, scales: { x: Object.assign(axis({ title: 'realised benefit per $1 of cost over the horizon' }), { ticks: tick }), y: Object.assign(axis({ title: '% of horizons' }), { min: 0, ticks: tick }) } },
      plugins: [HH.valueLabels({ format: function (v) { return v >= 1 ? fmt(v, 0) + '%' : ''; } })]
